<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait TemplateSnippetTenantAccessor
{
    private TemplateSnippetTenantVO $_tenant;
    public function getTenant(): TenantRef
    {
        return $this->_tenant->value();
    }
    public function tenant(): TemplateSnippetTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(TemplateSnippetTenantVO|TenantRef $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = TemplateSnippetTenantVO::from($tenant);
        return $copy;
    }
}
